interface Sink { send(message: string, id: string): Promise<void> }
type SinkFactory = () => Sink

class SinkRegistry {
  private map = new Map<string, SinkFactory>()
  register(name: string, factory: SinkFactory) { this.map.set(name, factory) }
  create(name: string): Sink | null { const f = this.map.get(name); return f ? f() : null }
}

class NotificationRouter {
  constructor(private registry: SinkRegistry) {}
  async route(routeId: string, message: string, id: string, sinkNames: string[]) {
    const sinks = sinkNames.map(n => this.registry.create(n)).filter(Boolean) as Sink[]
    await Promise.all(sinks.map(s => s.send(message, id)))
  }
}
